
ALTER TABLE "tasks" ADD COLUMN "series_id" BIGINT;
ALTER TABLE "tasks" ADD COLUMN "recurrence_modified_at" TIMESTAMPTZ(6);
ALTER TABLE "tasks" ADD COLUMN "scheduled_at" TIMESTAMPTZ(6);
CREATE INDEX "index_tasks_by_series_id" ON "tasks" ("series_id");

CREATE TYPE "series_frequency" AS ENUM ('daily', 'weekly', 'monthly');
CREATE TYPE "series_end" AS ENUM ('never', 'through', 'after');

CREATE TABLE "task_series" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "owner_id" BIGINT NOT NULL,
    "frequency" "series_frequency" NOT NULL,
    "interval" BIGINT NOT NULL,
    "time_zone" TEXT NOT NULL,
    "anchor" TIMESTAMP(6) NOT NULL,
    "end" "series_end" NOT NULL,
    "end_date" DATE,
    "end_count" BIGINT,
    "occurrence_count" BIGINT NOT NULL,
    "latest_task_id" BIGINT,
    "stopped_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX "index_task_series_by_owner_id" ON "task_series" ("owner_id");
